import hashlib
def dsha(b): return hashlib.sha256(hashlib.sha256(b).digest()).digest()
def varint(b,i):
    v=b[i]
    if v<0xfd: return v,i+1
    n={0xfd:2,0xfe:4,0xff:8}[v]; return int.from_bytes(b[i+1:i+1+n],'little'),i+1+n
def parse(h):
    b=bytes.fromhex(h); i=0
    ver=int.from_bytes(b[0:4],'little'); i=4
    segwit=False
    if b[i]==0 and b[i+1]==1: segwit=True; i+=2
    start_in=i
    nin,i=varint(b,i); ins=[]
    for _ in range(nin):
        prev=b[i:i+32][::-1].hex(); idx=int.from_bytes(b[i+32:i+36],'little'); i+=36
        l,i=varint(b,i); sig=b[i:i+l].hex(); i+=l
        seq=b[i:i+4].hex(); i+=4
        ins.append(dict(prev=prev,idx=idx,scriptSig=sig,seq=seq))
    nout,i=varint(b,i); outs=[]
    for _ in range(nout):
        val=int.from_bytes(b[i:i+8],'little'); i+=8
        l,i=varint(b,i); spk=b[i:i+l].hex(); i+=l
        outs.append(dict(value=val,spk=spk))
    end_io=i
    wit=[]
    if segwit:
        for _ in range(nin):
            n,i=varint(b,i); items=[]
            for _ in range(n):
                l,i=varint(b,i); items.append(b[i:i+l].hex()); i+=l
            wit.append(items)
    lock=int.from_bytes(b[i:i+4],'little'); i+=4
    assert i==len(b),(i,len(b))
    stripped=b[0:4]+b[start_in:end_io]+b[i-4:i]
    txid=dsha(stripped)[::-1].hex()
    wtxid=dsha(b)[::-1].hex()
    base=len(stripped); total=len(b); weight=base*3+total
    return dict(version=ver,segwit=segwit,ins=ins,outs=outs,wit=wit,locktime=lock,txid=txid,wtxid=wtxid,size=total,weight=weight)

