public static String printScriptAsOpCodes(byte[] script) {
    StringBuilder line = new StringBuilder();
    for (int i = 0; i < script.length;) {
        int val = Utilities.readUnsignedByte(script[i]);
        line.append(ScriptOpCodes.getOpCodeName(val));
        line.append(" ");
        i++;
        if ((val >= 1) && (val <= 75)) {
            for (int j = 0; j < val; j++) {
                line.append(byteToHex(script[i]));
                line.append(" ");
                i++;
            }
        } else if (val == 106) {
            while (i < script.length) {
                line.append(hexToAscii(byteToHex(script[i])));
                line.append(" ");
                i++;
            }
        }
    }
    return line.toString();
}

public static String printScriptAsOpCodes(byte[] script) {
    StringBuilder line = new StringBuilder();
    int i = 0;
    while (i < script.length) {
        int val = script[i++] & 0xff;
        line.append(ScriptOpCodes.getOpCodeName(val)).append(" ");
        int len = -1;
        if (val >= 1 && val <= 75) len = val;                       // push diretto
        else if (val == 76 && i + 1 <= script.length) len = script[i++] & 0xff;                     // OP_PUSHDATA1
        else if (val == 77 && i + 2 <= script.length) { len = (script[i] & 0xff) | (script[i+1] & 0xff) << 8; i += 2; } // OP_PUSHDATA2
        else if (val == 78 && i + 4 <= script.length) { len = (int) Utils.readUint32(script, i); i += 4; }                // OP_PUSHDATA4
        if (len >= 0) {
            if (i + len > script.length) { line.append("[push troncato]"); break; }  // niente ArrayIndexOutOfBounds
            for (int j = 0; j < len; j++) line.append(byteToHex(script[i++])).append(" ");
        }
        // OP_RETURN (106): nessun trattamento speciale, i dati seguono come push normali
    }
    return line.toString();
}

