NAMES = {0x00: "OP_0", 0x4c: "OP_PUSHDATA1", 0x4d: "OP_PUSHDATA2", 0x4e: "OP_PUSHDATA4",
         0x51: "OP_1", 0x52: "OP_2", 0x53: "OP_3", 0x6a: "OP_RETURN", 0x76: "OP_DUP",
         0x87: "OP_EQUAL", 0x88: "OP_EQUALVERIFY", 0xa9: "OP_HASH160",
         0xac: "OP_CHECKSIG", 0xae: "OP_CHECKMULTISIG"}

def disasm(script):
    out, i = [], 0
    while i < len(script):
        op = script[i]; i += 1
        if 0x01 <= op <= 0x4e:                       # push di dati
            if op <= 0x4b:
                n = op
            else:
                w = {0x4c: 1, 0x4d: 2, 0x4e: 4}[op]  # lunghezza su 1, 2 o 4 byte little endian
                if i + w > len(script):
                    out.append(NAMES[op] + " [troncato]"); break
                n = int.from_bytes(script[i:i + w], "little"); i += w
            if i + n > len(script):
                out.append(f"[push di {n} byte ma ne restano {len(script) - i}]"); break
            data = script[i:i + n]; i += n
            text = data.decode("ascii") if data and all(32 <= c < 127 for c in data) else None
            out.append(f'<{data.hex()}>' + (f' "{text}"' if text else ""))
        else:
            out.append(NAMES.get(op, f"OP_UNKNOWN_{op:#04x}"))
    return " ".join(out)

